contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an address and a value to attempt SetLogFile and SetMinSum.
    // No Ether needed.
    function run(address maybeLog, uint maybeMin) public payable {
        // Read initial initialized flag
        // There is no direct getter for `intitalized`, but we can infer by attempting SetMinSum/SetLogFile behavior.

        // First, attempt to call SetMinSum and SetLogFile before calling Initialized.
        bool before_setMinReverted;
        bool before_setLogReverted;
        // Try SetMinSum
        c.SetMinSum(maybeMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            before_setMinReverted = true;
        } else {
            before_setMinReverted = false;
        }
        // Try SetLogFile
        c.SetLogFile(maybeLog); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            before_setLogReverted = true;
        } else {
            before_setLogReverted = false;
        }

        // Now call Initialized()
        c.Initialized(); if (__ESBMC_reverted()) return;

        // After Initialized, both SetMinSum and SetLogFile SHOULD revert (they check intitalized and revert if true).
        bool after_setMinReverted;
        bool after_setLogReverted;
        c.SetMinSum(maybeMin); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            after_setMinReverted = true;
        } else {
            after_setMinReverted = false;
        }
        c.SetLogFile(maybeLog); bool __rev3 = __ESBMC_reverted(); if (__rev3) {
            after_setLogReverted = true;
        } else {
            after_setLogReverted = false;
        }

        // General rule: after Initialized() both SetMinSum and SetLogFile must revert.
        assert(after_setMinReverted && after_setLogReverted);
    }

    receive() external payable {}
}

