// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address maybeLog, uint256 maybeMin) internal {
        bool before_setMinReverted;
        bool before_setLogReverted;
        try c.SetMinSum(maybeMin) {
            before_setMinReverted = false;
        } catch {
            before_setMinReverted = true;
        }
        try c.SetLogFile(maybeLog) {
            before_setLogReverted = false;
        } catch {
            before_setLogReverted = true;
        }
        try c.Initialized() {} catch { return; }
        bool after_setMinReverted;
        bool after_setLogReverted;
        try c.SetMinSum(maybeMin) {
            after_setMinReverted = false;
        } catch {
            after_setMinReverted = true;
        }
        try c.SetLogFile(maybeLog) {
            after_setLogReverted = false;
        } catch {
            after_setLogReverted = true;
        }
        assertTrue(after_setMinReverted && after_setLogReverted);
    }

    function testFuzz_run(address maybeLog, uint256 maybeMin) public {
        vm.assume(maybeLog.code.length == 0 && uint160(maybeLog) > 0xffff && maybeLog != address(this) && maybeLog != address(c) && maybeLog != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && maybeLog != 0x000000000000000000636F6e736F6c652e6c6f67 && maybeLog != 0x4e59b44847b379578588920cA78FbF26c0B4956C && maybeLog != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(maybeLog, maybeMin);
    }

    receive() external payable {}
}
